 public static void Open(IWin32Window owner,string directory=null)
 {
  using(var mode=new DossierCharacterMode()){if(mode.ShowDialog(owner)!=DialogResult.OK)return;if(!mode.Assisted){var advanced=new FormEditorV2();try{advanced.OpenAdvancedCharacter(directory);StudioModule.ShowDocument(advanced,owner);}catch{advanced.Dispose();throw;}return;}}
  using(var creator=new DossierCharacterCreator())if(creator.ShowDialog(owner)==DialogResult.OK){var editor=new FormEditorV2();try{editor.OpenGeneratedCharacter(creator.Result,creator.EntryName,directory);StudioModule.ShowDocument(editor,owner);}catch{editor.Dispose();throw;}}
 }
 public DossierCharacterCreator()
 {
  DossierDpi.Initialize(this);Text="MPN Dossier REVANCED — Assisted character creation";Size=new Size(1160,840);MinimumSize=new Size(1000,700);StartPosition=FormStartPosition.CenterParent;
