  var basics=Page("Basics");Row(basics,"Name *",name);Row(basics,"Writing",autoWrite);Row(basics,"Personality",temperament);Row(basics,"Motivation",motivation);Row(basics,"Short name",shortName);Row(basics,"Title / role",role);Row(basics,"Faction",faction);Row(basics,"Experience",inheritLevel);Row(basics,"Level",level);Row(basics,"Durability",durability);Row(basics,"Movement",mobility);Row(basics,"Extra details\n(optional)",personality,116);
