 void FilterTemplates(){var previous=templates.SelectedItem;var list=DossierCharacterGenerator.Templates.Where(t=>(category.SelectedIndex==0||t.Category==(string)category.SelectedItem)&&(t.Name+" "+t.Description+" "+t.SourceId).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0).ToArray();templates.DataSource=list;if(list.Contains(previous))templates.SelectedItem=previous;UpdatePreview();}
 DossierCharacterBrief Brief()=>new DossierCharacterBrief{AutoWrite=autoWrite.Checked,Temperament=temperament.Text,Motivation=motivation.Text,Name=name.Text,ShortName=shortName.Text,Title=role.Text,Personality=personality.Text,Backstory=backstory.Text,Faction=(faction.SelectedItem as Choice)?.Value==null?(int?)null:int.Parse(((Choice)faction.SelectedItem).Value),Level=inheritLevel.Checked?(int?)null:(int)level.Value,Durability=durability.Text,Mobility=mobility.Text,Size=size.Text,Primary=(primary.SelectedItem as Choice)?.Value,Secondary=(secondary.SelectedItem as Choice)?.Value};
 void UpdatePreview(){var template=templates.SelectedItem as DossierCharacterTemplate;about.Text=template==null?"No matching templates. Try another category or search.":template.Description+"\r\n\r\nBased on: "+template.SourceId;try{if(template==null)throw new ArgumentException("Choose a template.");var brief=Brief();if(string.IsNullOrWhiteSpace(brief.Name))brief.Name="Your character";var result=DossierCharacterGenerator.Generate(template,brief);preview.Text=result["FullName"]+" / "+result["Title"]+"\r\n\r\nTemplate: "+template.Name+" ("+template.SourceId+")\r\nFaction: "+(ModEnums.Faction)(int)result["DefaultFaction"]+"\r\nLevel: "+result["Level"]+"\r\nHealth per corpus: "+result["Health"]+"\r\nCorpus blocks: "+result["CorpusBlocks"]?.Count()+"\r\nToughness: "+result["Toughness"]+"\r\nScale: "+result["Scale"]+"\r\nMovement: "+result["Speed"]+"\r\nAttributes (template order): "+result["Attributes"]+"\r\nPrimary: "+result["DefaultPrimary"]+"\r\nSecondary: "+result["DefaultSecondary"]+"\r\n\r\n"+result["Description"]+"\r\n\r\n"+(result["_DossierNotes"]==null?"No backstory note yet.":"Backstory note:\r\n"+result["_DossierNotes"]["entries"][0]["text"])+"\r\n\r\nLevel changes the Level field. Durability scales health/toughness; movement and size scale their template values. Other stats and abilities stay from the template. Review and test balance in game.";status.Text=string.IsNullOrWhiteSpace(name.Text)?"Only a name and template are required; all other settings are optional.":"Ready to review. Your template and database stay unchanged.";}catch(Exception ex){preview.Text=ex.Message;status.Text=ex.Message;}}
 void ReviewCharacter(){try{Result=DossierCharacterGenerator.Generate(templates.SelectedItem as DossierCharacterTemplate,Brief());EntryName=DossierCharacterGenerator.FileName(name.Text);DialogResult=DialogResult.OK;Close();}catch(Exception ex){status.Text=ex.Message;name.Focus();}}
